import java.util.Scanner;

public class P2 {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int length = input.nextInt();
        input.nextLine();
        String s = input.nextLine();

        int maxLength = 0;
        int currentLength = 0;
        int wordCount = 0;
        int insideWordLength = 0;
        int parenthesisDepth = 0;
        boolean hasOutsideLetter = false;
        boolean hasInsideLetter = false;
        boolean inside = false;

        for (int i = 0; i < length; i++) {
            char c = s.charAt(i);
            boolean isLeftParen = c == '(';
            boolean isRightParen = c == ')';

            if (isLeftParen) {
                inside = true;
                parenthesisDepth++;
                if (maxLength < currentLength) maxLength = currentLength;
                currentLength = 0;
                hasOutsideLetter = false;
            } else if (isRightParen) {
                inside = false;
                parenthesisDepth = 0;
                if (insideWordLength > 0) {
                    wordCount++;
                    insideWordLength = 0;
                }
            } else {
                if (parenthesisDepth > 0) inside = true;
            }

            if (!isLeftParen && !isRightParen) {
                if (!inside) {
                    if (c == '_') {
                        if (maxLength < currentLength) maxLength = currentLength;
                        currentLength = 0;
                        hasOutsideLetter = false;
                    } else {
                        hasOutsideLetter = true;
                    }
                    if (hasOutsideLetter) currentLength++;
                } else {
                    hasOutsideLetter = false;
                    if (c == '_') {
                        if (insideWordLength > 0) wordCount++;
                        insideWordLength = 0;
                        hasInsideLetter = false;
                    } else {
                        hasInsideLetter = true;
                    }
                    if (hasInsideLetter) insideWordLength++;
                }
            }
        }

        if (maxLength < currentLength) maxLength = currentLength;
        System.out.println(maxLength + " " + wordCount);
    }
}
